import XCTest
@testable import Arquemestre

/// Sincronizar pelo Wi-Fi: o iPhone calcula a mesma "impressão digital" que o Android/Windows (Kotlin) e grava
/// os pacotes que eles mandam do mesmo jeito. O fixture abaixo foi gerado pelo SyncCore.kt (mesmos arquivos).
final class SyncInteropTests: XCTestCase {
    private static let fixture = #"""
{"payloads":[{"images":{"foto1.jpg":""},"folder":{"name":"Obras 2026","id":"f1"},"v":1,"obj":{"pinned":false,"unit":"M","pages":[{"tpl":"ARAUJO","id":"p1","objs":[{"y1":20,"x1":10.5,"id":"o1","type":"dim","value":1234},{"pxH":80,"file":"foto1.jpg","id":"o2","type":"photo","pxW":100}]}],"createdMs":1700000000000,"v":3,"name":"Medi??o rua","id":"n-rua","locked":false,"folderId":"f1","trash":false},"meta":{"pinned":false,"pageCount":1,"createdMs":1,"name":"Medi??o rua","id":"n-rua","locked":false,"folderId":"f1","trash":false,"dimCount":1},"k":"note","id":"n-rua"},{"images":{},"v":1,"obj":{"pinned":false,"unit":"M","pages":[{"tpl":"ARAUJO","id":"p1","objs":[{"y1":20,"x1":10.5,"id":"o1","type":"dim","value":1234}]}],"createdMs":1700000000000,"v":3,"name":"Cozinha Maria \u2014 ?/? \"aspas\"","id":"n-same","locked":false,"folderId":null,"trash":false},"meta":{"pinned":false,"pageCount":1,"createdMs":1,"name":"Cozinha Maria \u2014 ?/? \"aspas\"","id":"n-same","locked":false,"folderId":null,"trash":false,"dimCount":1},"k":"note","id":"n-same"},{"images":{},"v":1,"obj":{"pinned":false,"unit":"M","pages":[{"tpl":"ARAUJO","id":"p1","objs":[{"y1":20,"x1":10.5,"id":"o1","type":"dim","value":1241}]}],"createdMs":1700000000000,"v":3,"name":"Sala Jo?o","id":"n-dif","locked":false,"folderId":null,"trash":false},"meta":{"pinned":false,"pageCount":1,"createdMs":1,"name":"Sala Jo?o","id":"n-dif","locked":false,"folderId":null,"trash":false,"dimCount":1},"k":"note","id":"n-dif"},{"v":1,"obj":{"cliente":{"nome":"Maria"},"estado":{"neg":-12.25,"big":123456789012,"nada":null,"W":3200,"H":2613.5,"z":0,"k":0.15763,"ok":true},"titulo":"Cozinha","id":"p1","updated":1700000000000},"k":"proj","id":"p1"},{"v":1,"obj":{"date":1700000000000,"city":"Frutal","client":"Maria","id":"q1","items":[{"unit":"m2","qty":2.5,"id":"i1","value":189.9,"desc":"MDF 15 mm"}]},"k":"quote","id":"q1"},{"v":1,"obj":{"kind":"VISITA","start":1700000500000,"id":"a1","title":"Medir sala\nlinha 2","remind":[60,1440]},"k":"agenda","id":"a1"}],"manifest":[{"h":"d4eba617d89e05407f7840da019426baac0c5eb995673d89b0f4e9f3dd091962","k":"note","id":"n-rua"},{"h":"5a5f18781e5ff1ae38a1d3526465660865f54719182cabea25699e2c71be57e5","k":"note","id":"n-same"},{"h":"2df24f38efe38d682e3c3f01d622fd00cf51471988d970ade6397e10b6ee8355","k":"note","id":"n-dif"},{"h":"4e9d1bbf1025d0493a6e7b380d5941b293a058c4f0748a4498578fb762034ada","k":"proj","id":"p1"},{"h":"c3ce736b6da9b4b5b0b00493eba7b99734c62884ad4a5bac6e7a31627e9eee71","k":"quote","id":"q1"},{"h":"60d229d11294a887ba5e7bec66e50f4b229257ac8ce391e4cef910a89ce6ae5a","k":"agenda","id":"a1"}],"files":{"projects/quotes.json":"W3siZGF0ZSI6MTcwMDAwMDAwMDAwMCwiY2l0eSI6IkZydXRhbCIsImNsaWVudCI6Ik1hcmlhIiwiaWQiOiJxMSIsIml0ZW1zIjpbeyJ1bml0IjoibTIiLCJxdHkiOjIuNSwiaWQiOiJpMSIsInZhbHVlIjoxODkuOSwiZGVzYyI6Ik1ERiAxNSBtbSJ9XX1d","projects/images/foto1.jpg":"","projects/index.json":"","projects/notes/n-same.json":"","projects/notes/n-dif.json":"","projects/notes/n-rua.json":"","projects/agenda.json":"W3sia2luZCI6IlZJU0lUQSIsInN0YXJ0IjoxNzAwMDAwNTAwMDAwLCJpZCI6ImExIiwidGl0bGUiOiJNZWRpciBzYWxhXG5saW5oYSAyIiwicmVtaW5kIjpbNjAsMTQ0MF19XQ==","moveis/projects.json":"W3siY2xpZW50ZSI6eyJub21lIjoiTWFyaWEifSwiZXN0YWRvIjp7Im5lZyI6LTEyLjI1LCJiaWciOjEyMzQ1Njc4OTAxMiwibmFkYSI6bnVsbCwiVyI6MzIwMCwiSCI6MjYxMy41LCJ6IjowLCJrIjowLjE1NzYzLCJvayI6dHJ1ZX0sInRpdHVsbyI6IkNvemluaGEiLCJpZCI6InAxIiwidXBkYXRlZCI6MTcwMDAwMDAwMDAwMH1d"}}

"""#

    private var root: URL!
    override func setUpWithError() throws {
        root = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    }
    override func tearDownWithError() throws { try? FileManager.default.removeItem(at: root) }

    private func fx() throws -> [String: Any] { try XCTUnwrap(JSONSerialization.jsonObject(with: Data(Self.fixture.utf8)) as? [String: Any]) }

    private func lay(_ dir: URL, _ files: [String: String]) throws {
        for (rel, b64) in files {
            let u = dir.appendingPathComponent(rel)
            try FileManager.default.createDirectory(at: u.deletingLastPathComponent(), withIntermediateDirectories: true)
            try XCTUnwrap(Data(base64Encoded: b64)).write(to: u)
        }
    }

    func testMesmoHashQueOKotlinParaOsMesmosArquivos() throws {
        let f = try fx()
        let a = root.appendingPathComponent("A")
        try lay(a, try XCTUnwrap(f["files"] as? [String: String]))
        let mine = Dictionary(uniqueKeysWithValues: SyncCore.manifest(a).map { ($0.key, $0.hash) })
        let kt = try XCTUnwrap(f["manifest"] as? [[String: Any]])
        XCTAssertEqual(mine.count, kt.count, "mesmos itens")
        for m in kt {
            let key = (m["k"] as! String) + "|" + (m["id"] as! String)
            XCTAssertEqual(mine[key], m["h"] as? String, "hash de \(key) igual ao do Android/Windows")
        }
    }

    func testPacotesDoKotlinGravamIgualSemDuplicar() throws {
        let f = try fx()
        let b = root.appendingPathComponent("B")
        let pays = try XCTUnwrap(f["payloads"] as? [[String: Any]])
        for p in pays { XCTAssertTrue(SyncCore.apply(b, p), "pacote \(p["k"] ?? "")") }
        for p in pays { XCTAssertTrue(SyncCore.apply(b, p)) } // de novo: troca, não duplica
        let kt = try XCTUnwrap(f["manifest"] as? [[String: Any]])
        let mine = SyncCore.manifest(b)
        XCTAssertEqual(mine.count, kt.count, "nada duplicado")
        let hs = Dictionary(uniqueKeysWithValues: mine.map { ($0.key, $0.hash) })
        for m in kt { XCTAssertEqual(hs[(m["k"] as! String) + "|" + (m["id"] as! String)], m["h"] as? String) }
        // foto e pasta vieram junto
        XCTAssertTrue(FileManager.default.fileExists(atPath: b.appendingPathComponent("projects/images/foto1.jpg").path))
        let idx = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: b.appendingPathComponent("projects/index.json"))) as? [String: Any])
        XCTAssertTrue(((idx["folders"] as? [[String: Any]]) ?? []).contains { ($0["name"] as? String) == "Obras 2026" })
        // o que o iPhone exporta volta igual (ida e volta)
        for m in kt {
            let p = try XCTUnwrap(SyncCore.export(b, m["k"] as! String, m["id"] as! String))
            XCTAssertEqual(SyncCore.hashOf(p["obj"]), m["h"] as? String)
        }
    }

    func testCodigoDaTelaEPacoteInvalido() {
        XCTAssertEqual(SyncNet.parse("10-4821", mine: ["192.168.0.5"]), SyncNet.Target(hosts: ["192.168.0.10"], pin: "4821", port: 47321))
        XCTAssertEqual(SyncNet.parse("192.168.1.20-1234-2", mine: []), SyncNet.Target(hosts: ["192.168.1.20"], pin: "1234", port: 47323))
        XCTAssertNil(SyncNet.parse("10-12", mine: ["192.168.0.5"]))
        XCTAssertNil(SyncNet.parse("300-1234", mine: ["192.168.0.5"]))
        XCTAssertFalse(SyncCore.apply(root, ["k": "note", "id": "../x", "obj": ["id": "../x", "pages": [Any]()]]))
        XCTAssertEqual(SyncCore.num(0.30000000000000004), "0.3")
        XCTAssertEqual(SyncCore.num(1.0), "1")
        XCTAssertEqual(SyncCore.num(-0.0), "0")
        XCTAssertEqual(SyncCore.num(1700000000000), "1700000000000")
        XCTAssertEqual(SyncCore.num(12.3456789), "12.345679")
    }
}
